insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (181, 'Welcome to Country', 'Murphy Wandin, Joy', NULL, '"Aboriginal communities across Australia have boundaries that are defined by mountain ranges and waterways. Traditionally, to cross these boundaries, permission is required. Each community has its own way of greeting, but the practice shares a common name: a Welcome to Country. Aunty Joy Murphy Wandin, the senior Aboriginal elder of the Wurundjeri people, channels her passion for storytelling into a remarkable and utterly unique picture book that invites readers to discover some of the history and traditions of her people. Indigenous artist Lisa Kennedy gives the Wurundjeri Welcome to Country form in beautiful paintings rich with blues and browns, as full of wonder and history as the tradition they depict" -- Publisher website.', 'verified', '181_welcome_to_country.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (182, 'Rabbit, Soldier, Angel, Thief', 'Nannestad, Katrina', NULL, 'Award-winning writer Katrina Nannestad transports us to Russia and the Great Patriotic War and into the life of Sasha, a soldier at only six years old. It''s spring, 1942. The sky is blue, the air is warm and sweet with the scent of flowers. And then everything is gone. Wood splinters and Mama screams and the nearest soldier seizes her roughly by the arms. My sister pokes her bruised face out from beneath the table and shouts, ''Run, Sasha! Run!'' So I run. I run like a rabbit. Alone in a war-torn world, a young boy cannot survive without family, without a home, without an army of his own. But is love ever enough when the world is at war? From the award-winning author of We Are Wolves comes the story of a young boy who becomes a soldier at six, fighting in the only way he can - with love.', 'verified', '182_rabbit_soldier_angel_thief.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (183, 'For Love', 'Neri, Cristina', NULL, 'Award-winning author Penelope Neri completes her acclaimed Viking trilogy with the spellbinding story of an Irish-Viking prince cursed by a hellish fate--and the aristocratic British beauty who risks her life to love him.', 'verified', '183_for_love.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (184, 'Hold On! Saving the Spotted Handfish', 'Newton, Gina M', 'Rachel Tribout', 'A beautiful picture book about a quirky little fish that is famous for walking on its ''hands''.', 'verified', '184_hold_on_saving_the_spotted_handfish.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (185, 'I Wanna New Room', 'Orloff, Karen', 'David Catrow', 'A hilarious companion to I Wanna Iguana that all siblings will relate to. Ever since their baby sister came along, Alex has been forced to share a room with his little brother, Ethan, and it''s a nightmare. Ethan always breaks stuff, snores like a walrus, and sticks crayons up his nose. No hardworking, well-behaved, practically grown-up boy like Alex should have to put up with that! Writing letters to his mom convinced her to let him get his pet iguana, so Alex puts pencil to paper again, this time determined to get his own room. Though all of his powers of persuasion can''t get his dad to expand the house, he does come through with a fun alternative to give Alex some space of his own. Look for more stories highlighting Alex''s negotiation skills: I Wanna Iguana and I Wanna Go Home.', 'verified', '185_i_wanna_new_room.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (186, 'I Wanna Iguana', 'Orloff, Karen', 'David Catrow', 'Hilarious notes between a son and his mom show how kid logic can be very persuasive. Alex just has to convince his mom to let him have an iguana, so he puts his arguments in writing. He promises that she won''t have to feed it or clean its cage or even see it if she doesn''t want to. Of course Mom imagines life with a six-foot-long iguana eating them out of house and home. Alex''s reassures her: It takes fifteen years for an iguana to get that big. I''ll be married by then and probably living in my own house His mom''s reply: How are you going to get a girl to marry you when you own a giant reptile? Kis will be in hysterics as the negotiations go back and forth through notes, and the lively, imaginative illustrations showing their polar opposite dreams of life with an iguana take the humor to even higher heights. Look for more stories highlighting Alex''s powers of persuasion: I Wanna New Room and I Wanna Go Home.', 'verified', '186_i_wanna_iguana.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (187, 'The Perfect Pet', 'Palatini, Margie', NULL, 'A humorous story about Elizabeth who wants the perfect pet but discovers her ''perfect'' choice might not be quite right. This entertaining tale explores expectations versus reality and finding unexpected happiness.', 'needs_review', '187_the_perfect_pet.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (188, 'The Boy Who Tried to Shrink His Name', 'Parappukkaran, Sandhya', 'Michelle Pereira', 'When Zimdalamashkermishkada starts a new school, he knows he’s got to do something about his long name. ​ When no amount of shrinking, folding or crumpling works, he simply settles for Zim – but deep down, it doesn’t feel right. It’s not until a new friend sees him for who he truly is that Zimdalamashkermishkada finds the confidence to step boldly into his long name. ​ A warm and uplifting story that encourages young readers to celebrate their individuality, and shows how no-one should ever have to shrink themselves down to fit in.​ Winner of the 2022 Children''s Book Council of Australia''s Award for New Illustrator Selected as the January/February 2023 American Booksellers Association''s Kids'' Indie Next Title 2023 Outstanding International Book for USBBY (United States Board on Books for Young People) Shortlisted for the 2023 Speech Pathology Book of the Year award (Ages 3 to 5) ​ ​', 'verified', '188_the_boy_who_tried_to_shrink_his_name.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (189, 'Bowerbird Blues', 'Parker, Aura', NULL, 'I am a collector. Always looking, finding... and keeping! Bowerbird loves BLUE. Magnificent cobalt. Brilliant, vibrant blue! But something is missing. What could it be? This picture book follows a bowerbird searching for blue across sea, sky and city, collecting vibrant treasures that ultimately attract something greater and more fulfilling than he could ever have imagined.', 'verified', '189_bowerbird_blues.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (190, 'Seven Seas of Fleas', 'Petzold, Dave', NULL, 'A flying boy and seven bees are chased by fleas, but an unexpected friendship forms. Bryce McFee is an ordinary boy bored with washing the flea-ridden family dog. So, he escapes to his imagination and flies across the backyard with a dandelion and seven bees. Trouble strikes when a swarm of pesky fleas gives chase, threatening to ruin his adventure. Ultimately, an unlikely friendship is formed between the flying boy and the fleas. A fun rhyming story that exercises the imagination.', 'verified', '190_seven_seas_of_fleas.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (191, 'Paradise Sands: A Story of Enchantment', 'Pinfold, Levi', NULL, 'A captivating tale of eerie places and mystical bargains, sumptuously illustrated by Kate Greenaway Medalist Levi Pinfold. When a young girl and her older brothers step into the ghostly Paradise Sands hotel, they fall under the rule of the mysterious Teller. The girl makes a deal with the commanding creature to free them all from his haunting paradise - and let them return to their mother, white roses in hand. But can the girl, determined as she is, hold up her side of the bargain? A contemporary story with the feel of a classic fairy tale, Levi Pinfold''s Paradise Sands is lush with enchanting illustrations, rendered in a muted palette with the artist''s distinctive stylistic realism.', 'verified', '191_paradise_sands.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (192, 'Two Mates', 'Prewett, Maggie', 'Maggie Prewett', 'Two Mates is the true story of the special mateship between two young boys who have grown up together in the coastal town of Broome in Australia''s north-west. Jack is Indigenous and Raf is a non- Indigenous boy who has spina bifida. Jack and Raf take the reader on a journey of their daily life growing up in Broome. Together they search for hermit crabs, go hunting for barni, fish for salmon, explore the markets, eat satays and dress up as superheros. The fact that Raf is in a wheelchair is only revealed at the end of the story.', 'verified', '192_two_mates.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (193, 'Shirley Purdie: My Story, Ngaginybe Jarragbe', 'Purdie, Shirley', NULL, 'Told in English and Gija, this is Shirley Purdie''s life story, depicted alongside her stunning paintings. In My Story, Ngaginybe Jarragbe, Shirley shares vignettes of her life growing up on Mabel Downs station, and her Gija Culture, Country and Dreaming. She explains her Dreaming is Echidna Dreaming and she teaches us about bush fruit and hunting. She also shares the story of her working life, as a maid in the homestead on Mabel Downs station, and later in life as an artist, and how her mum taught her how to paint her Country. Shirley Purdie is a famous Australian artist who lives in Warmun community, in the remote Kimberley region of Western Australia. This is her first children''s picture book.', 'verified', '193_shirley_purdie_my_story_ngaginybe_jarragbe.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (194, 'Australia: Country of Colour', 'Racklyeft, Jess', NULL, 'With its vivid red dirt, big blue skies, wild green bushland and golden sandy beaches, Australia is a country of extraordinary colour. Here is a celebration of the stunning plants and animals of this colourful country, from vibrant pink Flame Peas to startling blue Fairy Wrens, electric yellow Billy Buttons, glossy black Tasmanian Devils, and many more. Come and take a closer look at nature''s paintbox and the rainbow of life that lives in Australia, from one of our best-loved picture book creators.', 'verified', '194_australia_country_of_colour.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (195, 'Polly and Buster - The Wayward Witch & the Feelings Monster', 'Rippin, Sally', NULL, 'If Polly and Buster walk past each other in the street, they never say hello. After all, whoever heard of a witch being friends with a monster? But Polly the witch and Buster the feelings monster have been best friends forever. Somehow, they''ve managed to keep their friendship a secret. Until one day, when everything changes...', 'verified', '195_polly_and_buster_the_wayward_witch_the_feelings_monster.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (196, 'Tiddalick - The Frog Who Caused a Flood', 'Roennfeldt, Robert', NULL, 'An Australian Classic Reimagined Journey into the heart of Australian Aboriginal Dreamtime with Tiddalick the Frog Who Caused a Flood by Robert Roennfeldt. This timeless tale captures imaginations with its whimsical storytelling and vivid illustrations. The Tale That Made a Splash! Tiddalick was so thirsty that he drank up all the rivers and billabongs in the land. And the other animals had to find a way to get the water back. Why This Book Resonates with Kids *Problem-Solving- Encourages critical thinking as children ponder how the other animals solve their water crisis. *Cultural Exposure- An introduction to the rich tapestry of Aboriginal folklore. *Eco-Awareness- Sparks conversations about environmental stewardship. *Stunning Art- Vivid illustrations that captivate young minds. A Timeless Tale for Modern Kids Wrap your child in the magic and wonder of an age-old tale that has been passed down through generations. With its engaging narrative and lush illustrations, Tiddalick the Frog Who Caused a Flood offers a unique blend of education and entertainment, making it an instant favourite for children and adults alike.', 'verified', '196_tiddalick_the_frog_who_caused_a_flood.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (197, 'Jetty Jumping', 'Rowe, Andrea', NULL, 'While Milla''s friends take big, brave jumps off the jetty, Milla stays on the blistering wood, scared of what lurks below. But when Milla accidentally falls off the edge, she discovers the beauty of the deep, dark sea - and her summer changes forever. Andrea Rowe and Hannah Sommerville perfectly capture the challenges of childhood - and the joy of letting go - in this homage to summer.', 'verified', '197_jetty_jumping.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (198, 'Sunday Skating', 'Rowe, Andrea', NULL, 'Clancy’s friends skate through the quiet Sunday streets, while Clancy feels self-conscious, and embarrassed, that he’s just a beginner. His board stays tucked under his arm; his feet stay firmly on the ground. But his friends aren’t giving up on him and Clancy realises the only way forward is to step on his board and try … even if he might fall. Andrea Rowe and Hannah Sommerville transport us back to the world of their award-winning picture book, Jetty Jumping, with a story about self-doubt, courage and the power of friendship. ‘A story that captures the true essences of camaraderie, courage and self-belief … Sunday Skating encapsulates beauty, nostalgia and playfulness for lovers of skating, and for those willing to try. Just like good friends and the power of courage, this book will pick you up when you fall.’ Books+Publishing A Bookstagram Kid''s Choice Award for 2023', 'verified', '198_sunday_skating.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (199, 'Harry Potter and the Philosopher''s Stone', 'Rowling, J.K.', NULL, 'When a letter arrives for unhappy but ordinary Harry Potter, a decade-old secret is revealed to him that apparently he''s the last to know. His parents were wizards, killed by a Dark Lord''s curse when Harry was just a baby, and which he somehow survived. Leaving his unsympathetic aunt and uncle for Hogwarts, a wizarding school brimming with ghosts and enchantments, Harry stumbles upon a sinister adventure when he finds a three-headed dog guarding a room on the third floor. Then he hears of a missing stone with astonishing powers which could be valuable, dangerous, or both.', 'verified', '199_harry_potter_and_the_philosophers_stone.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (200, 'Harry Potter and the Chamber of Secrets', 'Rowling, J.K.', NULL, 'A special new edition in celebration of the 20th anniversary of the publication of Harry Potter and the Sorcerer''s Stone, with a stunning new cover illustration by Caldecott Medalist Brian Selznick. The Dursleys were so mean and hideous that summer that all Harry Potter wanted was to get back to the Hogwarts School for Witchcraft and Wizardry. But just as he''s packing his bags, Harry receives a warning from a strange, impish creature named Dobby who says that if Harry Potter returns to Hogwarts, disaster will strike. And strike it does. For in Harry''s second year at Hogwarts, fresh torments and horrors arise, including an outrageously stuck-up new professor, Gilderoy Lockhart, a spirit named Moaning Myrtle who haunts the girls'' bathroom, and the unwanted attentions of Ron Weasley''s younger sister, Ginny. But each of these seem minor annoyances when the real trouble begins, and someone - or something - starts turning Hogwarts students to stone. Could it be Draco Malfoy, a more poisonous rival than ever? Could it possibly be Hagrid, whose mysterious past is finally told? Or could it be the one everyone at Hogwarts most suspects... Harry Potter himself! This gorgeous new edition in celebration of the 20th anniversary of the publication of Harry Potter and the Sorcerer''s Stone features a newly designed cover illustrated by Caldecott Medalist Brian Selznick, as well as the beloved original interior decorations by Mary GrandPré.', 'verified', '200_harry_potter_and_the_chamber_of_secrets.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (201, 'Harry Potter and Prisoner of Azkaban', 'Rowling, J.K.', NULL, 'During his third year at Hogwarts School for Witchcraft and Wizardry, Harry Potter must confront the devious and dangerous wizard responsible for his parents deaths.', 'verified', '201_harry_potter_and_prisoner_of_azkaban.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (202, 'Harry Potter and the Goblet of Fire', 'Rowling, J.K.', NULL, 'Fourteen-year-old Harry Potter joins the Weasleys at the Quidditch World Cup, then enters his fourth year at Hogwarts Academy where he is mysteriously entered in an unusual contest that challenges his wizarding skills, friendships and character, amid signs that an old enemy is growing stronger.', 'verified', '202_harry_potter_and_the_goblet_of_fire.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (203, 'Harry Potter and the Order of the Phoenix', 'Rowling, J.K.', NULL, 'Harry is furious that he has been abandoned at the Dursleys'' house for the summer, for he suspects that Voldemort is gathering an army, that he himself could be attacked, and that his so-called friends are keeping him in the dark. Finally being rescued by wizard bodyguards, he discovers that Dumbledore is regrouping the Order of the Phoenix - a secret society first formed years ago to fight Voldemort. But the Ministry of Magic is against the Order, lies are being spread by the wizards'' tabloid, the Daily Prophet, and Harry fears that he may have to take on this epic battle against evil alone.', 'verified', '203_harry_potter_and_the_order_of_the_phoenix.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (204, 'Harry Potter and the Half Blood Prince', 'Rowling, J.K.', NULL, '''In a brief statement on Friday night, Minister for Magic Cornelius Fudge confirmed that He Who Must Not Be Named has returned to this country and is once more active. "It is with great regret that I must confirm that the wizard styling himself Lord - well, you know who I mean - is alive and among us again," said Fudge.'' These dramatic words appeared in the final pages of Harry Potter and the Order of the Phoenix. In the midst of this battle of good and evil, Harry Potter and the Half-Blood Prince takes up the story of Harry Potter''s sixth year at Hogwarts School of Witchcraft and Wizardry, with Voldemort''s power and followers increasing day by day . . .', 'verified', '204_harry_potter_and_the_half_blood_prince.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (205, 'Harry Potter and the Deathly Hallows', 'Rowling, J.K.', NULL, '''His hand closed automatically around the fake Horcrux, but in spite of everything, in spite of the dark and twisting path he saw stretching ahead for himself, in spite of the final meeting with Voldemort he knew must come, whether in a month, in a year, or in ten, he felt his heart lift at the thought that there was still one last golden day of peace left to enjoy with Ron and Hermione.'' With these words Harry Potter and the Half-Blood Prince draws to a close. And here, in this seventh and final book, Harry discovers what fate truly has in store for him as he inexorably makes his way to that final meeting with Voldemort. In this thrilling climax to the phenomenally bestselling series, J.K. Rowling will reveal all to her eagerly waiting readers.', 'verified', '205_harry_potter_and_the_deathly_hallows.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (206, 'Gary', 'Rudge, Leila', NULL, 'Gary, a grounded racing pigeon, dreams of exploring the world - until the day he falls into an adventure of his very own. A story of perseverance and being comfortable in your own skin, perfect for anyone who has ever felt like the odd one out, this is the story one pigeon''s big adventure. Most of the time, Gary is just like the other racing pigeons, eating and sleeping and dreaming of adventure. There''s just one thing that separates him from the ordinary pigeons: he can''t fly. When his friends set off in their travel basket, Gary expects to stay at home, organizing his scrapbook of travel mementos and imagining far-off places. But when he accidentally falls into the travel basket and ends up a very long way from home, he discovers that flying might not be the only way to have adventures...', 'verified', '206_gary.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (207, 'Winston and the Indoor Cat', 'Rudge, Leila', NULL, 'A story about seeing what life is like on the other side of the window. Now in paperback!Two very different cats, Winston, a free-spirited explorer, and The Indoor Cat, lover of leisure, form a friendship and show each other how different their lives could be. Can The Indoor Cat be enticed by outdoor adventure? Will Winston be tempted by a life of indoor luxury?', 'verified', '207_winston_and_the_indoor_cat.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (208, 'The Old Woman Who Named Things', 'Rylant, Cynthia', NULL, 'An old woman who has outlived all her friends is reluctant to become too attached to the stray dog that visits her each day.', 'verified', '208_the_old_woman_who_named_things.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (209, 'When I was Young in the Mountains', 'Rylant, Cynthia', NULL, 'Caldecott Honor Book! "An evocative remembrance of the simple pleasures in country living; splashing in the swimming hole, taking baths in the kitchen, sharing family times, each is eloquently portrayed here in both the misty-hued scenes and in the poetic text." -Association for Childhood Education International', 'verified', '209_when_i_was_young_in_the_mountains.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (210, 'Night in the Country', 'Rylant, Cynthia', NULL, 'There is no night so dark, so black as night in the country. And while the people dream of daytime things, the nighttime world awakens. Owls swoop, a rabbit patters, and in the yard an apple falls -- pump! -- from the tree. Listen. Go to the window. Across the field a light glows. Who else is up so late? Who else watches and hears the sights and sounds of night in the country -- the many stirrings of silence, the many colors of the dark? Lyrical text and velvety pictures present a very different kind of nighttime: a mysterious, moving night that will lull small children to sleep.', 'verified', '210_night_in_the_country.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (211, 'In November', 'Rylant, Cynthia', 'Jill Kastner', 'In November, the air grows cold and the earth and all of its creatures prepare for winter. Animals seek food and shelter. And people gather together to celebrate their blessings with family and friends. Cynthia Rylant''s lyrical language and Jill Kastner''s rich, cozy paintings capture the cherished moments of this autumn month--the moments we spend together and the ones we witness in the world around us.', 'verified', '211_in_november.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (212, 'Scarecrow', 'Rylant, Cynthia', NULL, 'From a Newbery Medal-winning author, a look at life from a scarecrow’s point of view, accompanied by “magnificent” illustrations (School Library Journal). Scarecrows. They perch high above gardens and fields, with borrowed coats and button eyes and pie-pan hands that glint in the sun. What else is there to know about them? Perhaps more than we realize. Newbery Medalist Cynthia Rylant’s rich and poignant story, powerfully illustrated by Lauren Stringer, will resonate deeply in the hearts of readers, who just might find themselves seeing the world in a whole new way. “Rylant lyrically imagines the scarecrow as a grateful ‘witness to life,’ while the acrylic paintings evoke a warm, even nostalgic sense of plenty.”—Publishers Weekly "Rylant uses casual, conversational language with simple elegance and pleasing rhythms.”—School Library Journal “Rylant is in fine form.”—Kirkus Reviews', 'verified', '212_scarecrow.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (213, 'Little People, Big Dreams - Ru Paul', 'Sanchez Vegara, Isabel', NULL, 'Meet RuPaul, the shape-shifter, performer, supermodel, and host of RuPaul''s Drag Race. Even before little Ru was born, a fortune teller told his mom that he would one day be famous... It was only a matter of time before he figured out how. Playing dress-up was his favorite game, and that''s where he felt most comfortable. Ru went on to study performing arts and then moved to New York to mix things up in a punk band. Later, drag was a way to express himself as an artist. He found success for himself, then wanted to help others find theirs. He inspires us to do what feels right and love ourselves. This witty and wise book features stylish and quirky illustrations and extra facts at the back, including a biographical timeline with historical photos and a detailed profile of the inspiring performer''s life.', 'verified', '213_little_people_big_dreams_ru_paul.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (214, 'Little People, Big Dreams - Charles Darwin', 'Sanchez Vegara, Isabel', NULL, 'Meet Charles Darwin, the scientist who changed the way people see the world. Although he didn''t do very well at school, Charles Darwin was passionately curious about wildlife, humans, and plants. After a journey to South America, he developed his landmark theory: that all living things are related. Today, he is regarded as one of the most brilliant scientists who ever lived, and a hero to those who dare to think differently. This inspiring book features stylish and quirky illustrations and extra facts at the back, including a biographical timeline with historical photos and a detailed profile of the iconic naturalist''s life.', 'verified', '214_little_people_big_dreams_charles_darwin.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (215, 'Little People, Big Dreams - Dolly Parton', 'Sanchez Vegara, Isabel', NULL, 'Meet Dolly Parton, the singer-songwriter and businesswoman. Little Dolly grew up in Tennessee in a family "as poor as dirt." She started performing at an early age, singing on local radio and television. After graduating high school, she moved to Nashville to pursue her singing dreams. Her managers wanted her to sing pop, but she followed her heart to sing and write country songs. Her heart was right-Dolly became a musical superstar, but she never forgot where she came from. She now uses her wealth to give back to people, children, and animals in need. This moving book features stylish and quirky illustrations and extra facts at the back, including a biographical timeline with historical photos and a detailed profile of the singer''s life.', 'verified', '215_little_people_big_dreams_dolly_parton.jpg');
